3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create-owner request once the maximum number of owners has already been
11	 * created today, responding 429. "Today" is measured by each owner's
12	 * {@code registrationDate}: at most {@value #DAILY_LIMIT} owners may carry today's date.
13	 * Runs after {@link ValidateOwnerFields} and before {@link BuildOwner}, so the owner
14	 * being created is not yet counted.
15	 */
16	public class EnsureDailyCreateLimit {
17	
18	    /** Maximum number of owners that may be registered in a single day. */
19	    static final int DAILY_LIMIT = 100;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DailyCreateLimitException {
23	        LocalDate today = LocalDate.now();
24	        long count = ownerRepository.findAll().stream()
25	                .filter(o -> today.equals(o.getRegistrationDate()))
26	                .count();
27	        if (count >= DAILY_LIMIT) {
28	            throw new DailyCreateLimitException(DAILY_LIMIT);
29	        }
30	    }
31	}
