6	 * {@code DailyCreateLimitExceptionHandler}, which responds 429.
7	 */
8	public class DailyCreateLimitException extends Exception {
9	
10	    public DailyCreateLimitException(int limit) {
11	        super("The daily limit of " + limit + " owner registrations has already been reached");
12	    }
13	}
